Search Facilities.code:
// Search facilities in a region, e.g. to sync the master list into DHIS2.
// post() pages through all results automatically.
post('Facility/GetFacilities', {
  pageNumber: 1,
  showPerPage: 100,
  regionId: [$.data.regionId], // array of ids from Location/Regions
  facilityTypeId: $.data.facilityTypeIds, // optional array of ids, from Lookup?name=FacilityType
});

Get Facility By MFR ID.code:
// Fetch one facility by its MFR id.
get('Facility', {
  query: { id: $.data.mfrId }, // e.g. '1071644'
});

Find Facilities By Name.code:
// Find facilities by name, optionally narrowed to a woreda.
get('Facility/All', {
  query: {
    name: $.data.facilityName, // e.g. '010 Kombolcha Health Post'
    woredaId: $.data.woredaId, // optional
  },
});

Export Facilities As CSV.code:
// Export facilities in a zone as CSV text.
request(
  // 1) HTTP method.
  'POST',
  // 2) Path.
  'Facility/ExportCSV',
  // 3) Same filters as GetFacilities (id filters are arrays).
  { zoneId: [$.data.zoneId] },
  // 4) Return the raw CSV string.
  { parseAs: 'text' }
);

List Lookup Values.code:
// List reference data, e.g. facility types, for mapping ids to names.
get('Lookup', {
  query: { name: 'FacilityType' }, // or 'Ownership', 'OperationalStatus', ...
});
